from pathlib import Pathfrom PIL import Imagefrom src import maindef test_process_image_generates_copy(tmp_path, monkeypatch):    image_path = tmp_path / "test.jpg"    image = Image.new("RGB", (800, 600))    image.save(image_path)    monkeypatch.setattr(        main,        "create_copy",        lambda image: "Copy generado de prueba."    )    result = main.process_image(image_path)    assert result == "Copy generado de prueba."    def test_process_image_rejects_missing_image(tmp_path):    image_path = tmp_path / "missing.jpg"    try:        main.process_image(image_path)        assert False, "Se esperaba un ValueError"    except ValueError as error:        assert str(error) == (            f"La imagen no existe: {image_path}"        )